def nutrition(r):
    if r.get("nonut"): return None
    k = p = f = 0.0
    for _, zs in r["groups"]:
        for (_m, _n, key, g) in zs:
            if key:
                a, b, c = NUT[key]; k += a * g / 100; p += b * g / 100; f += c * g / 100
    return (int(round(k / 2 / 10) * 10), int(round(p / 2)), int(round(f / 2)))
if __name__ == "__main__":
    for g in GOODIES:
        for r in g["recipes"]:
            print(r["id"], r["t"], nutrition(r), len(r["plants"]))
